skin:
#s76 .stage{background:radial-gradient(110% 130% at 50% -10%,#161616,#0a0a0a 60%);color:#ededed}
#s76 .stage::before{content:'';position:absolute;inset:0;background:radial-gradient(40% 30% at 50% 0%,#ffffff08,transparent 65%);pointer-events:none}
#s76 .d-nav{background:#121212cc;border:1px solid #ffffff12;border-radius:10px;backdrop-filter:blur(10px)}
#s76 .d-logo{font-weight:700}
#s76 .d-links span{opacity:.58;font-size:11.5px}#s76 .d-links span:hover{opacity:1;background:#ffffff0c;border-radius:6px}
#s76 .d-p{color:#9c9c9c}
#s76 .d-btn{background:#fff;color:#000;border-radius:8px;font-weight:600}
#s76 .d-btn:hover{background:#e5e5e5}
#s76 .d-btn.ghost{background:#ffffff0a;color:#ccc;border:1px solid #ffffff17}
#s76 .d-input{background:#141414;border:1px solid #ffffff14;color:#ededed;border-radius:9px;font-family:var(--mono);font-size:12px}
#s76 .d-tog.onn{background:#fff}
#s76 .d-badge{background:#ffffff0d;color:#bbb;border-radius:5px;font-family:var(--mono);font-size:10px}
#s76 .d-prog{height:2px;background:#ffffff10}#s76 .d-prog i{background:#0070f3}
#s76 .d-card{background:#131313;border:1px solid #ffffff0f;border-radius:10px}
